catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
    var ga = new GlideAjax('x_1771422_refund_0.refund_details');
    ga.addParam('sysparm_name', 'getOrderInfo');
    ga.addParam('sysparm_orderId', newValue);
    ga.getXML(getOrderDetails);

    function getOrderDetails(response) {
        var ans = response.responseXML.documentElement.getAttribute("answer");
        var res = JSON.parse(ans);
		alert(res);
        if (res) {
			alert('if Inside');
			g_form.setValue('full_name', res.full_name);
			g_form.setValue('city', res.city);
			g_form.setValue('pincode', res.pincode);
			g_form.setValue('state', res.state);
			g_form.setValue('street_line2', res.street_line_2);
			g_form.setValue('sdoor_no_street_line_1', res.door_no_street_line_1);
			g_form.setValue('district', res.district);
            g_form.setValue('street_line3', res.street_line_3);
            g_form.setValue('contact_number', res.contact_number);
            g_form.setValue('email', res.email);
        } 
    }
   //Type appropriate comment here, and begin script below

}
